#include "SketchRotate.h"
#include "SketchAxis3d.h"
#include <QJsonArray>
#include <QMap>
#include <QUuid>
#include <QPointF>
#include <cmath>
#include <numbers>
#include <stdexcept>
namespace {
void need(bool v,const QString& m){if(!v)throw std::invalid_argument(m.toStdString());}
QSet<QString> ids(const QJsonArray& a){QSet<QString> r;for(const auto& v:a){need(v.isString() && !v.toString().isEmpty() && !r.contains(v.toString()),"Rotate membership requires distinct IDs");r.insert(v.toString());}return r;}
QMap<QString,QJsonObject> rows(const QJsonObject& p,const char* key){QMap<QString,QJsonObject> r;for(const auto& v:p[key].toArray())r[v.toObject()["id"].toString()]=v.toObject();return r;}
bool mentions(const QJsonValue& v,const QSet<QString>& targets){if(v.isString())return targets.contains(v.toString());if(v.isArray())for(const auto& x:v.toArray())if(mentions(x,targets))return true;if(v.isObject())for(const auto& x:v.toObject())if(mentions(x,targets))return true;return false;}
QJsonObject axis(const QJsonObject& p,const QJsonObject& g){need(SketchAxis3d::validate(p).isEmpty(),"Rotate requires a valid normal +Z construction Line");for(const auto& v:p["constructionLines3d"].toArray()){const auto a=v.toObject();if(a["id"]==g["axisLineId"]){need(a["start"].toObject()["id"]==g["axisStartPointId"] && a["end"].toObject()["id"]==g["axisEndPointId"],"Rotate axis endpoint identity changed");return a;}}need(false,"Rotate axis is missing or foreign");return {};}
QJsonObject output(const QJsonObject& s,const QJsonObject& a,double degrees){const auto pivot=a["start"].toObject();const double x=pivot["uMm"].toDouble(),y=pivot["vMm"].toDouble(),u=s["uMm"].toDouble()-x,v=s["vMm"].toDouble()-y,t=degrees*std::numbers::pi/180;return {{"uMm",x+u*std::cos(t)-v*std::sin(t)},{"vMm",y+u*std::sin(t)+v*std::cos(t)}};}
void finite(const QJsonObject& p,const char* key,double limit=100000){need(p[key].isDouble() && std::isfinite(p[key].toDouble()) && std::abs(p[key].toDouble())<=limit,QString("Rotate %1 must be finite within ±%2").arg(key).arg(limit));}
}
namespace SketchRotate {
QSet<QString> owned(const QJsonObject& p,bool points){QSet<QString> r;for(const auto& v:p["rotateGroups"].toArray()){const auto g=v.toObject();if(points)for(const auto& s:g["sourcePoints"].toArray())r.insert(s.toObject()["pointId"].toString());else for(const auto& id:g["entityIds"].toArray())r.insert(id.toString());}return r;}
bool touches(const QJsonObject& p,const QJsonValue& v){return mentions(v,owned(p)+owned(p,true));}
QString validate(const QJsonObject& p){try{
 if(!p.contains("rotateGroups"))return {};need(p["rotateGroups"].isArray() && p["rotateGroups"].toArray().size()<=1 && p["plane"]=="XY","Rotate supports one retained XY profile");const auto es=rows(p,"entities"),ps=rows(p,"points");
 for(const auto& row:p["rotateGroups"].toArray()){
 const auto g=row.toObject();need(g.size()==11 && !QUuid(g["id"].toString()).isNull() && g["type"]=="rotate","Invalid retained Rotate definition");finite(g,"angleDeg",360000);const auto a=axis(p,g);need(g["entityIds"].isArray() && g["sourcePoints"].isArray() && g["topology"].isArray() && g["constraints"].isArray() && g["dimensions"].isArray(),"Invalid Rotate membership arrays");const auto selected=ids(g["entityIds"].toArray());need(selected.size()==4 && g["sourcePoints"].toArray().size()==4 && g["topology"].toArray().size()==4,"Rotate owns four Lines and four vertices");QSet<QString> vertices,topology;QMap<QString,QStringList> neighbors;
 for(const auto& v:g["sourcePoints"].toArray()){const auto s=v.toObject();const auto id=s["pointId"].toString();need(s.size()==3 && ps.contains(id) && !vertices.contains(id) && id!=p["originPointId"],"Invalid Rotate source identity");finite(s,"uMm");finite(s,"vMm");const auto expected=output(s,a,g["angleDeg"].toDouble()),actual=ps.value(id);need(std::abs(actual["uMm"].toDouble()-expected["uMm"].toDouble())<=1e-9 && std::abs(actual["vMm"].toDouble()-expected["vMm"].toDouble())<=1e-9,"Rotate output cache changed; edit its angle or axis");vertices.insert(id);}
 for(const auto& v:g["topology"].toArray()){const auto t=v.toObject(),e=es.value(t["entityId"].toString());const auto id=t["entityId"].toString(),x=t["startPointId"].toString(),y=t["endPointId"].toString();need(t.size()==3 && selected.contains(id) && !topology.contains(id) && e["type"]=="line" && !e["construction"].toBool() && !e["centerline"].toBool() && e["startPointId"]==t["startPointId"] && e["endPointId"]==t["endPointId"] && vertices.contains(x) && vertices.contains(y) && x!=y,"Rotate topology changed or unsupported");topology.insert(id);neighbors[x].append(y);neighbors[y].append(x);}
 QSet<QString> connected;QStringList ordered;QString cursor=*vertices.begin(),prev;for(int n=0;n<4;++n){need(neighbors[cursor].size()==2 && !connected.contains(cursor),"Rotate requires a connected closed four-Line loop");connected.insert(cursor);ordered.append(cursor);const auto next=neighbors[cursor][0]==prev?neighbors[cursor][1]:neighbors[cursor][0];prev=cursor;cursor=next;}need(cursor==*vertices.begin() && connected==vertices,"Rotate selection is disconnected");QMap<QString,QPointF> source;for(const auto& v:g["sourcePoints"].toArray()){const auto s=v.toObject();source[s["pointId"].toString()]={s["uMm"].toDouble(),s["vMm"].toDouble()};}auto cross=[](const QPointF& a,const QPointF& b){return a.x()*b.y()-a.y()*b.x();};QPointF xy[4];double area=0;for(int n=0;n<4;++n)xy[n]=source.value(ordered[n]);for(int n=0;n<4;++n)area+=cross(xy[n],xy[(n+1)%4]);need(std::abs(area)>1e-6,"Rotate requires a nondegenerate profile");for(int n=0;n<2;++n){const auto a=xy[n],b=xy[n+1],c=xy[n+2],d=xy[(n+3)%4];need(!(cross(b-a,c-a)*cross(b-a,d-a)<=0 && cross(d-c,a-c)*cross(d-c,b-c)<=0),"Rotate requires a simple noncrossing profile");}const auto targets=selected+vertices;
 for(const auto& e:es)if(!selected.contains(e["id"].toString()))need(!mentions(e,vertices),"Rotate shares an endpoint with unselected geometry");for(auto it=p.begin();it!=p.end();++it)if(!QStringList{"rotateGroups","points","entities","constraints","dimensions","constructionLines3d"}.contains(it.key()))need(!mentions(it.value(),targets),"Rotate geometry has another owner/reference");
 QJsonArray cs,ds;for(const auto& v:p["constraints"].toArray()){const auto c=v.toObject();if(!mentions(c,targets))continue;const auto type=c["type"].toString();need(QStringList{"parallel","perpendicular","equal","coincident"}.contains(type),"Rotate refuses non-invariant/fixed relation "+c["id"].toString()+" ("+type+")");for(const auto& id:c["entityIds"].toArray())need(selected.contains(id.toString()),"Rotate relation crosses unselected entity "+c["id"].toString());for(const auto& id:c["pointIds"].toArray())need(vertices.contains(id.toString()),"Rotate relation crosses unselected point "+c["id"].toString());cs.append(c);}
 for(const auto& v:p["dimensions"].toArray()){const auto d=v.toObject();if(!mentions(d,targets))continue;need(d["kind"]=="linear" && d["pointIds"].isArray() && d["pointIds"].toArray().size()==2 && !d.contains("entityId") && !d.contains("entityIds"),"Rotate supports internal point-to-point linear dimensions only: "+d["id"].toString());for(const auto& id:d["pointIds"].toArray())need(vertices.contains(id.toString()),"Rotate dimension crosses unselected point "+d["id"].toString());ds.append(d);}
 need(cs==g["constraints"] && ds==g["dimensions"],"Rotate source relations/size are immutable in this slice; source-size composition is deferred");
 }
 return {};}catch(const std::exception& e){return QString::fromUtf8(e.what());}}
QJsonObject source(const QJsonObject& p){auto r=p;auto points=p["points"].toArray();for(const auto& v:p["rotateGroups"].toArray())for(const auto& s:v.toObject()["sourcePoints"].toArray())for(int n=0;n<points.size();++n)if(points[n].toObject()["id"]==s.toObject()["pointId"]){auto point=points[n].toObject();point["uMm"]=s.toObject()["uMm"];point["vMm"]=s.toObject()["vMm"];points[n]=point;}r["points"]=points;r.remove("rotateGroups");return r;}
QJsonObject materialize(const QJsonObject& p,const QJsonArray& groups){auto r=p;auto points=p["points"].toArray();for(const auto& v:groups){const auto g=v.toObject(),a=axis(p,g);for(const auto& v:g["sourcePoints"].toArray()){const auto s=v.toObject(),out=output(s,a,g["angleDeg"].toDouble());finite(out,"uMm");finite(out,"vMm");bool found=false;for(int n=0;n<points.size();++n)if(points[n].toObject()["id"]==s["pointId"]){auto point=points[n].toObject();point["uMm"]=out["uMm"];point["vMm"]=out["vMm"];points[n]=point;found=true;}need(found,"Rotate source point is unavailable");}}r["points"]=points;if(!groups.isEmpty())r["rotateGroups"]=groups;return r;}
QJsonObject create(const QJsonObject& p,const QJsonArray& entityIds,const QString& axisId,double angle,const QString& groupId){need(validate(p).isEmpty(),"Existing Rotate definition is invalid");auto groups=p["rotateGroups"].toArray();QJsonObject g;
 if(groupId.isEmpty()){need(groups.isEmpty(),"This sketch already has a Rotate; edit it");const auto selected=ids(entityIds);need(selected.size()==4,"Rotate requires four distinct Line IDs");need(std::abs(angle)>=1e-9,"Enter a nonzero rotation angle");const auto es=rows(p,"entities");QSet<QString> vertices;QJsonArray ss,ts,cs,ds;for(const auto& id:entityIds){const auto e=es.value(id.toString());need(e["type"]=="line","Rotate requires ordinary authored Lines");vertices.insert(e["startPointId"].toString());vertices.insert(e["endPointId"].toString());ts.append(QJsonObject{{"entityId",id},{"startPointId",e["startPointId"]},{"endPointId",e["endPointId"]}});}const auto targets=selected+vertices;for(const auto& v:p["points"].toArray())if(vertices.contains(v.toObject()["id"].toString()))ss.append(QJsonObject{{"pointId",v.toObject()["id"]},{"uMm",v.toObject()["uMm"]},{"vMm",v.toObject()["vMm"]}});for(const auto& v:p["constraints"].toArray())if(mentions(v,targets))cs.append(v);for(const auto& v:p["dimensions"].toArray())if(mentions(v,targets))ds.append(v);g={{"id",QUuid::createUuid().toString(QUuid::WithoutBraces)},{"type","rotate"},{"entityIds",entityIds},{"sourcePoints",ss},{"topology",ts},{"constraints",cs},{"dimensions",ds}};
 }else{need(groups.size()==1 && groups.first().toObject()["id"]==groupId,"Retained Rotate group is unavailable");g=groups.first().toObject();need(entityIds.isEmpty() || ids(entityIds)==ids(g["entityIds"].toArray()),"Edit Rotate retains its original four Lines");}
 QJsonObject a;for(const auto& v:p["constructionLines3d"].toArray())if(v.toObject()["id"]==axisId)a=v.toObject();need(!a.isEmpty(),"Select this sketch's normal 3D construction Line");g["axisLineId"]=axisId;g["axisStartPointId"]=a["start"].toObject()["id"];g["axisEndPointId"]=a["end"].toObject()["id"];g["angleDeg"]=angle;const auto r=materialize(source(p),QJsonArray{g});const auto error=validate(r);need(error.isEmpty(),error);return r;
}
}
